package com.ChaTop.Backend.Models;import jakarta.persistence.*;@Entity@Table(name = "users")public class User {    @Id    @GeneratedValue(strategy = GenerationType.IDENTITY)    private int id;    @Column(name="name",unique=true)    private String name;    @Column(name="email",unique=true)    private String email;    @Column(name="password")    private String password;    public int getId() {        return id;    }    public void setId(int id) {        this.id = id;    }    public String getPassword() {        return password;    }    public void setPassword(String password) {        this.password = password;    }    public String getEmail() {        return email;    }    public void setEmail(String email) {        this.email = email;    }    public String getName() {        return name;    }    public void setName(String name) {        this.name = name;    }}